package com.styleshop.product.config;
import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.HttpServletResponse; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.web.SecurityFilterChain; import java.util.Map;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain chain(HttpSecurity h,ObjectMapper m)throws Exception{h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/api/products/**","/api/categories/**","/images/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter())).authenticationEntryPoint((q,r,e)->err(r,m,401,"JWT 無效或已過期"))).exceptionHandling(e->e.accessDeniedHandler((q,r,x)->err(r,m,403,"僅限管理員")));return h.build();}private JwtAuthenticationConverter converter(){var g=new JwtGrantedAuthoritiesConverter();g.setAuthoritiesClaimName("roles");g.setAuthorityPrefix("ROLE_");var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(g);return c;}private void err(HttpServletResponse r,ObjectMapper m,int s,String msg)throws java.io.IOException{r.setStatus(s);r.setContentType(MediaType.APPLICATION_JSON_VALUE);r.setCharacterEncoding("UTF-8");m.writeValue(r.getWriter(),Map.of("message",msg));}}
